1	package darksafe
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"math"
9		"math/big"
10		"regexp"
11		"sort"
12		"strconv"
13		"strings"
14		"unicode"
15		"unicode/utf16"
16		"unicode/utf8"
17	)
18	
19	// Point 是一条序列上某个时间戳的采样值。
20	type Point struct {
21		Timestamp int64   `json:"timestamp"`
22		Value     float64 `json:"value"`
23	}
24	
25	// SeriesView 是结果输出用的一条序列视图，标签按键升序呈现。
26	type SeriesView struct {
27		Name   string            `json:"name"`
28		Labels map[string]string `json:"labels"`
29		Points []Point           `json:"points"`
30	}
31	
32	// QuerySeries 是查询结果中的一条序列：完整身份与区间内点的个数及算术平均值。
33	type QuerySeries struct {
34		Name    string            `json:"name"`
35		Labels  map[string]string `json:"labels"`
36		Count   int               `json:"count"`
37		Average float64           `json:"average"`
38	}
39	
40	// QueryResult 是一次区间均值查询成功后的结果，只读，不改变存储。
41	type QueryResult struct {
42		Status string        `json:"status"`
43		Op     string        `json:"op"`
44		Series []QuerySeries `json:"series"`
45	}
46	
47	// BatchResult 是一批采样点写入成功后的结果。
48	type BatchResult struct {
49		Status     string       `json:"status"`
50		Added      int          `json:"added"`
51		Duplicates int          `json:"duplicates"`
52		Series     []SeriesView `json:"series"`
53	}
54	
55	// SeriesRef 标识一条序列：指标名加完整标签集合。
56	// 缺少某个标签与该标签值为空字符串属于不同序列。
57	type SeriesRef struct {
58		Name   string            `json:"name"`
59		Labels map[string]string `json:"labels"`
60	}
61	
62	// Conflict 描述同一序列同一时间戳已存在不同的值。
63	type Conflict struct {
64		Series    SeriesRef `json:"series"`
65		Timestamp int64     `json:"timestamp"`
66		Existing  float64   `json:"existing"`
67		Submitted float64   `json:"submitted"`
68	}
69	
70	// LineError 是一行（一批）输入失败后的结构化结果。
71	// Line 由命令入口按从 1 开始的行号填入；Index 为采样点在批次内从 1 开始的位置，
72	// 整行 JSON 无法解析或不是数组时 Index 为零并省略。
73	type LineError struct {
74		Status   string    `json:"status"`
75		Line     int       `json:"line,omitempty"`
76		Index    int       `json:"index,omitempty"`
77		Error    string    `json:"error"`
78		Conflict *Conflict `json:"conflict,omitempty"`
79	}
80	
81	// MetricStore 保存一次命令运行期间已写入的指标数据，仅存在于内存中，进程结束即丢弃。
82	type MetricStore struct {
83		series map[seriesID]*storedSeries
84	}
85	
86	// seriesID 是序列的规范身份，标签书写顺序不影响身份。
87	type seriesID struct {
88		name string
89		// sig 为排序后标签键值对的长度前缀拼接，避免不同写法产生碰撞。
90		sig string
91	}
92	
93	type storedSeries struct {
94		ref    SeriesRef
95		points map[int64]float64
96	}
97	
98	// NewMetricStore 创建一个空的指标存储。
99	func NewMetricStore() *MetricStore {
100		return &MetricStore{series: make(map[seriesID]*storedSeries)}
101	}
102	
103	// cloneLabels 返回标签集合的独立副本；空标签仍复制为非 nil 的空集合，
104	// 调用方对副本的增删改不影响存储中的序列身份。
105	func cloneLabels(labels map[string]string) map[string]string {
106		out := make(map[string]string, len(labels))
107		for k, v := range labels {
108			out[k] = v
109		}
110		return out
111	}
112	
113	func sortedKeys(m map[string]string) []string {
114		keys := make([]string, 0, len(m))
115		for k := range m {
116			keys = append(keys, k)
117		}
118		sort.Strings(keys)
119		return keys
120	}
121	
122	func makeSeriesID(name string, labels map[string]string) seriesID {
123		var b strings.Builder
124		for _, k := range sortedKeys(labels) {
125			v := labels[k]
126			fmt.Fprintf(&b, "%d:%s;%d:%s;", len(k), k, len(v), v)
127		}
128		return seriesID{name: name, sig: b.String()}
129	}
130	
131	// labelPair 是标签键值对字典序比较的单元。
132	type labelPair struct {
133		Key, Value string
134	}
135	
136	func sortedPairs(labels map[string]string) []labelPair {
137		keys := sortedKeys(labels)
138		pairs := make([]labelPair, len(keys))
139		for i, k := range keys {
140			pairs[i] = labelPair{Key: k, Value: labels[k]}
141		}
142		return pairs
143	}
144	
145	func compareLabelPairs(a, b []labelPair) int {
146		n := len(a)
147		if len(b) < n {
148			n = len(b)
149		}
150		for i := 0; i < n; i++ {
151			if a[i].Key != b[i].Key {
152				return strings.Compare(a[i].Key, b[i].Key)
153			}
154			if a[i].Value != b[i].Value {
155				return strings.Compare(a[i].Value, b[i].Value)
156			}
157		}
158		switch {
159		case len(a) < len(b):
160			return -1
161		case len(a) > len(b):
162			return 1
163		}
164		return 0
165	}
166	
167	var (
168		jsonIntegerRE = regexp.MustCompile(`^-?(0|[1-9][0-9]*)$`)
169		jsonNumberRE  = regexp.MustCompile(`^-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?$`)
170	)
171	
172	// ProcessLine 处理一行非空输入：JSON 数组为写入批次，JSON 对象为查询/操作。
173	// 成功时返回 BatchResult 或 *QueryResult；失败返回 *LineError（Index 始终为零）。
174	func (s *MetricStore) ProcessLine(line string) (any, *LineError) {
175		top, ok, lerr := decodeTopValue(line)
176		if lerr != nil {
177			return nil, lerr
178		}
179		switch ok {
180		case '[':
181			var items []json.RawMessage
182			if err := json.Unmarshal(top, &items); err != nil {
183				return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
184			}
185			return s.ingestItems(items)
186		case '{':
187			return s.queryFromObject(top)
188		default:
189			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
190		}
191	}
192	
193	// IngestLine 解析并写入一行（一批）采样点。成功返回 BatchResult；
194	// 失败返回 *LineError，此时此前各批数据保留、本批不写入任何数据。
195	func (s *MetricStore) IngestLine(line string) (*BatchResult, *LineError) {
196		top, ok, lerr := decodeTopValue(line)
197		if lerr != nil {
198			return nil, lerr
199		}
200		if ok != '[' {
201			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples"}
202		}
203		var items []json.RawMessage
204		if err := json.Unmarshal(top, &items); err != nil {
205			return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
206		}
207		return s.ingestItems(items)
208	}
209	
210	// QueryLine 解析并执行一行查询对象。成功返回 QueryResult；查询只读，不改变存储。
211	func (s *MetricStore) QueryLine(line string) (*QueryResult, *LineError) {
212		top, ok, lerr := decodeTopValue(line)
213		if lerr != nil {
214			return nil, lerr
215		}
216		if ok != '{' {
217			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a query object"}
218		}
219		return s.queryFromObject(top)
220	}
221	
222	// validateLineText 在 JSON 解析之前强制整行文本合法：原始字节必须是合法
223	// UTF-8，字符串内的 Unicode 转义必须表示有效字符。编码层/JSON 解析器会把
224	// 非法字节或未配对代理项静默替换成 U+FFFD，使损坏文本混入合法序列（被误判为
225	// 重复、冲突或错误命中查询），因此这里一律拒绝而不是修补后继续。
226	//
227	// 逐字节扫描、只在字符串内部识别转义：跳过词法空白与全部非字符串 token。
228	// 被转义的反斜杠（\\）后的 "uXXXX" 只是普通文本，不会被当成 Unicode 转义。
229	func validateLineText(line string) *LineError {
230		if !utf8.ValidString(line) {
231			return &LineError{Status: "error", Error: "invalid JSON: input is not valid UTF-8 text"}
232		}
233		inString := false
234		for i := 0; i < len(line); i++ {
235			c := line[i]
236			if !inString {
237				if c == '"' {
238					inString = true
239				}
240				continue
241			}
242			switch c {
243			case '"':
244				inString = false
245			case '\\':
246				if i+1 >= len(line) {
247					break // 悬空反斜杠：交给 JSON 解析器报错
248				}
249				if line[i+1] != 'u' {
250					i++ // 单字符转义（\\、\"、\n 等），跳过被转义字符
251					continue
252				}
253				// i 指向 '\'，i+1 指向 'u'；转义占据 i..i+5。
254				r, size := decodeJSONHexEscape(line, i+1)
255				if size == 0 {
256					return &LineError{Status: "error", Error: "invalid JSON: invalid Unicode escape sequence"}
257				}
258				if !utf16.IsSurrogate(r) {
259					i += 5
260					continue
261				}
262				if r >= 0xDC00 {
263					// 单独出现的低代理项。
264					return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
265				}
266				// 高代理项后必须紧接另一个表示低代理项的 \uXXXX 转义。
267				loPos := i + 6 // 第一个转义之后的字符位置
268				if loPos+1 >= len(line) || line[loPos] != '\\' || line[loPos+1] != 'u' {
269					return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
270				}
271				lo, loSize := decodeJSONHexEscape(line, loPos+1)
272				if loSize == 0 || lo < 0xDC00 || lo > 0xDFFF {
273					return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
274				}
275				i = loPos + loSize // 跳到第二转义的最后一个十六进制位，循环自增后越出
276			}
277		}
278		return nil
279	}
280	
281	// decodeJSONHexEscape 解析 line[pos:] 处的 "uXXXX"（pos 指向 'u'），
282	// 返回其码元与占用字节数（固定为 5）；不足四个十六进制数字时 size 为 0。
283	func decodeJSONHexEscape(line string, pos int) (rune, int) {
284		if pos+4 >= len(line) {
285			return 0, 0
286		}
287		var v rune
288		for j := pos + 1; j <= pos+4; j++ {
289			c := line[j]
290			var d rune
291			switch {
292			case c >= '0' && c <= '9':
293				d = rune(c - '0')
294			case c >= 'a' && c <= 'f':
295				d = rune(c-'a') + 10
296			case c >= 'A' && c <= 'F':
297				d = rune(c-'A') + 10
298			default:
299				return 0, 0
300			}
301			v = v<<4 | d
302		}
303		return v, 5
304	}
305	
306	// decodeTopValue 解析单行中唯一的 JSON 值并返回其原始内容与首个非空白字节
307	// （'[' 或 '{'）。整个值无法解析、为空或存在尾随内容时返回 *LineError。
308	func decodeTopValue(line string) (json.RawMessage, byte, *LineError) {
309		if lerr := validateLineText(line); lerr != nil {
310			return nil, 0, lerr
311		}
312		dec := json.NewDecoder(strings.NewReader(line))
313		var top json.RawMessage
314		if err := dec.Decode(&top); err != nil {
315			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
316		}
317		// 第一个 JSON 值之后只允许输入结束（Decoder 自动跳过尾随空白）。
318		if err := dec.Decode(new(json.RawMessage)); err != io.EOF {
319			if err == nil {
320				err = fmt.Errorf("unexpected content after the JSON value")
321			}
322			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
323		}
324		trimmed := strings.TrimSpace(string(top))
325		if len(trimmed) == 0 || (trimmed[0] != '[' && trimmed[0] != '{') {
326			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
327		}
328		return top, trimmed[0], nil
329	}
330	
331	// fieldReader 从 dec 读取并校验当前字段的值，写入调用方持有的结果。
332	// 采样点与查询对象各自注册自己允许的字段及字段含义。
333	type fieldReader func(dec *json.Decoder) error
334	
335	// parseStrictObject 是写入采样点与查询对象共用的严格对象校验骨架：
336	// 仅允许 fields 中列出的字段（未知字段先于判重被拒绝），同一对象内按转义还原
337	// 后的字段名判重（即使两个值相同也拒绝；判重不跨对象、不跨层级），按输入次序
338	// 逐字段调用对应的 fieldReader，对象结束后要求输入恰好耗尽，最后按 required
339	// 的顺序报告缺失的必填字段。notObjectMsg 与 trailingMsg 由调用方给出，
340	// 保留各自输入的措辞。
341	func parseStrictObject(raw json.RawMessage, notObjectMsg, trailingMsg string, required []string, fields map[string]fieldReader) error {
342		dec := json.NewDecoder(bytes.NewReader(raw))
343		dec.UseNumber()
344	
345		tok, err := dec.Token()
346		if err != nil {
347			return err
348		}
349		if d, ok := tok.(json.Delim); !ok || d != '{' {
350			return fmt.Errorf("%s", notObjectMsg)
351		}
352	
353		present := make(map[string]bool)
354		for dec.More() {
355			keyTok, err := dec.Token()
356			if err != nil {
357				return err
358			}
359			key := keyTok.(string)
360			read, ok := fields[key]
361			if !ok {
362				return fmt.Errorf("unknown field %q", key)
363			}
364			if present[key] {
365				return fmt.Errorf("duplicate field %q", key)
366			}
367			present[key] = true
368			if err := read(dec); err != nil {
369				return err
370			}
371		}
372		if _, err := dec.Token(); err != nil { // 消耗 '}'
373			return err
374		}
375		if _, err := dec.Token(); err != io.EOF {
376			if err == nil {
377				return fmt.Errorf("%s", trailingMsg)
378			}
379			return err
380		}
381	
382		for _, field := range required {
383			if !present[field] {
384				return fmt.Errorf("missing required field %q", field)
385			}
386		}
387		return nil
388	}
389	
390	// readNameField 读取写入与查询共用的指标名字段：必须是非空字符串。
391	func readNameField(dec *json.Decoder, dst *string) error {
392		t, err := dec.Token()
393		if err != nil {
394			return err
395		}
396		s, ok := t.(string)
397		if !ok {
398			return fmt.Errorf(`field "name" must be a string`)
399		}
400		if s == "" {
401			return fmt.Errorf(`field "name" must be a non-empty string`)
402		}
403		*dst = s
404		return nil
405	}
406	
407	// readInt64Field 读取 int64 毫秒整数字段（timestamp/start/end）：
408	// 必须是 JSON 整数且在 int64 范围内，数字字符串、布尔值、带小数点一律拒绝。
409	func readInt64Field(dec *json.Decoder, field string, dst *int64) error {
410		n, err := nextJSONNumber(dec, field)
411		if err != nil {
412			return err
413		}
414		v, err := parseJSONInt(n)
415		if err != nil {
416			return fmt.Errorf("field %q: %s", field, err)
417		}
418		*dst = v
419		return nil
420	}
421	
422	// readFiniteFloatField 读取采样值字段：必须是可表示为有限 float64 的 JSON 数字。
423	func readFiniteFloatField(dec *json.Decoder, field string, dst *float64) error {
424		n, err := nextJSONNumber(dec, field)
425		if err != nil {
426			return err
427		}
428		v, err := parseFiniteFloat(n)
429		if err != nil {
430			return fmt.Errorf("field %q: %s", field, err)
431		}
432		*dst = v
433		return nil
434	}
435	
436	// readLabelsField 读取标签对象字段并写入 dst；notObjectMsg 保留各输入侧措辞。
437	func readLabelsField(dec *json.Decoder, notObjectMsg string, dst *map[string]string) error {
438		labels, err := parseLabels(dec, notObjectMsg)
439		if err != nil {
440			return err
441		}
442		*dst = labels
443		return nil
444	}
445	
446	type parsedSample struct {
447		name   string
448		ts     int64
449		value  float64
450		labels map[string]string
451	}
452	
453	// parseSample 对单个采样点做严格校验：仅允许四个已知字段、拒绝重复键，
454	// 标量必须是精确的 JSON 类型，timestamp 为 int64 整数，value 为有限 float64。
455	func parseSample(raw json.RawMessage) (parsedSample, error) {
456		var p parsedSample
457		p.labels = map[string]string{}
458		err := parseStrictObject(raw,
459			"each sample must be a JSON object",
460			"unexpected content after the sample object",
461			[]string{"name", "timestamp", "value"},
462			map[string]fieldReader{
463				"name":      func(dec *json.Decoder) error { return readNameField(dec, &p.name) },
464				"timestamp": func(dec *json.Decoder) error { return readInt64Field(dec, "timestamp", &p.ts) },
465				"value":     func(dec *json.Decoder) error { return readFiniteFloatField(dec, "value", &p.value) },
466				"labels": func(dec *json.Decoder) error {
467					return readLabelsField(dec, `field "labels" must be an object of string keys to string values`, &p.labels)
468				},
469			})
470		return p, err
471	}
472	
473	// parseLabels 从 dec 读取一个标签对象并做统一校验：必须是 JSON 对象
474	// （否则返回调用方给出的 notObjectMsg，写入与查询措辞不同），键为非空字符串、
475	// 值为字符串（空串合法，键值均不做清理），重复键一律拒绝。
476	// 返回的集合不含标签时也是非 nil 的空 map，与省略 labels 的语义一致。
477	func parseLabels(dec *json.Decoder, notObjectMsg string) (map[string]string, error) {
478		t, err := dec.Token()
479		if err != nil {
480			return nil, err
481		}
482		d, ok := t.(json.Delim)
483		if !ok || d != '{' {
484			return nil, fmt.Errorf("%s", notObjectMsg)
485		}
486		labels := map[string]string{}
487		for dec.More() {
488			labelKeyTok, err := dec.Token()
489			if err != nil {
490				return nil, err
491			}
492			labelKey := labelKeyTok.(string)
493			if labelKey == "" {
494				return nil, fmt.Errorf(`field "labels": label keys must be non-empty strings`)
495			}
496			valTok, err := dec.Token()
497			if err != nil {
498				return nil, err
499			}
500			labelVal, ok := valTok.(string)
501			if !ok {
502				return nil, fmt.Errorf(`field "labels": value of label %q must be a string`, labelKey)
503			}
504			if _, dup := labels[labelKey]; dup {
505				return nil, fmt.Errorf(`field "labels": duplicate label key %q`, labelKey)
506			}
507			labels[labelKey] = labelVal
508		}
509		if _, err := dec.Token(); err != nil { // 消耗 '}'
510			return nil, err
511		}
512		return labels, nil
513	}
514	
515	func nextJSONNumber(dec *json.Decoder, field string) (json.Number, error) {
516		t, err := dec.Token()
517		if err != nil {
518			return "", err
519		}
520		n, ok := t.(json.Number)
521		if !ok {
522			return "", fmt.Errorf(`field %q must be a JSON number`, field)
523		}
524		return n, nil
525	}
526	
527	func parseJSONInt(n json.Number) (int64, error) {
528		s := string(n)
529		if !jsonIntegerRE.MatchString(s) {
530			return 0, fmt.Errorf("must be a JSON integer in milliseconds")
531		}
532		v, err := strconv.ParseInt(s, 10, 64)
533		if err != nil {
534			return 0, fmt.Errorf("must be within int64 range")
535		}
536		return v, nil
537	}
538	
539	func parseFiniteFloat(n json.Number) (float64, error) {
540		s := string(n)
541		if !jsonNumberRE.MatchString(s) {
542			return 0, fmt.Errorf("must be a JSON number")
543		}
544		v, err := strconv.ParseFloat(s, 64)
545		if err != nil || math.IsInf(v, 0) || math.IsNaN(v) {
546			return 0, fmt.Errorf("must be a finite number representable as float64")
547		}
548		return v, nil
549	}
550	
551	// ingestItems 完成全部采样点校验与冲突检测后再统一提交，保证整批原子性。
552	func (s *MetricStore) ingestItems(items []json.RawMessage) (*BatchResult, *LineError) {
553		type pending struct {
554			id  seriesID
555			ref SeriesRef
556			ts  int64
557			val float64
558		}
559	
560		added := 0
561		// 本批已确定身份的点（含与已写入数据重复的点），用于批内去重与冲突检测。
562		seen := make(map[seriesID]map[int64]float64)
563		// 仅记录需要落盘的新增点；校验全部通过后才提交。
564		commits := make([]pending, 0, len(items))
565	
566		failAt := func(index int, msg string) *LineError {
567			return &LineError{Status: "error", Index: index, Error: msg}
568		}
569		conflictAt := func(index int, ref SeriesRef, ts int64, existing, submitted float64) *LineError {
570			return &LineError{
571				Status: "error",
572				Index:  index,
573				Error: fmt.Sprintf("conflict: series %s at timestamp %d already has value %s, submitted %s",
574					ref, ts, formatFloat(existing), formatFloat(submitted)),
575				Conflict: &Conflict{
576					// 标签必须复制：冲突结果是本次失败的独立记录，
577					// 调用方修改它不能改动已存序列的身份。
578					Series:    SeriesRef{Name: ref.Name, Labels: cloneLabels(ref.Labels)},
579					Timestamp: ts,
580					Existing:  existing,
581					Submitted: submitted,
582				},
583			}
584		}
585	
586		for i, item := range items {
587			pos := i + 1
588			p, err := parseSample(item)
589			if err != nil {
590				return nil, failAt(pos, err.Error())
591			}
592	
593			id := makeSeriesID(p.name, p.labels)
594			ref := SeriesRef{Name: p.name, Labels: p.labels}
595	
596			if byTS, ok := seen[id]; ok {
597				if old, ok := byTS[p.ts]; ok {
598					if old != p.value {
599						return nil, conflictAt(pos, ref, p.ts, old, p.value)
600					}
601					// 同批内重复出现且数值相同：重复，成功忽略。
602					continue
603				}
604			}
605			if sr, ok := s.series[id]; ok {
606				if old, ok := sr.points[p.ts]; ok {
607					if old != p.value {
608						return nil, conflictAt(pos, sr.ref, p.ts, old, p.value)
609					}
610					// 与此前批次已写入的值相同：重复，成功忽略。
611					if seen[id] == nil {
612						seen[id] = map[int64]float64{}
613					}
614					seen[id][p.ts] = p.value
615					continue
616				}
617			}
618	
619			added++
620			if seen[id] == nil {
621				seen[id] = map[int64]float64{}
622			}
623			seen[id][p.ts] = p.value
624			commits = append(commits, pending{id: id, ref: ref, ts: p.ts, val: p.value})
625		}
626	
627		// 全部采样点合法且无冲突，原子提交本批新增点。
628		for _, c := range commits {
629			sr := s.series[c.id]
630			if sr == nil {
631				sr = &storedSeries{ref: c.ref, points: map[int64]float64{}}
632				s.series[c.id] = sr
633			}
634			sr.points[c.ts] = c.val
635		}
636	
637		return s.snapshot(added, len(items)-added), nil
638	}
639	
640	// formatFloat 以 JSON 数值风格格式化 float64：1 与 1.0 均显示为 1。
641	func formatFloat(v float64) string {
642		return strconv.FormatFloat(v, 'g', -1, 64)
643	}
644	
645	type parsedQuery struct {
646		name   string
647		start  int64
648		end    int64
649		labels map[string]string
650	}
651	
652	// queryFromObject 严格解析查询对象并执行只读区间均值查询。
653	func (s *MetricStore) queryFromObject(raw json.RawMessage) (*QueryResult, *LineError) {
654		q, err := parseQuery(raw)
655		if err != nil {
656			return nil, &LineError{Status: "error", Error: err.Error()}
657		}
658		if q.start > q.end {
659			return nil, &LineError{Status: "error", Error: fmt.Sprintf(
660				`invalid range: "start" must not be greater than "end" (%d > %d)`, q.start, q.end)}
661		}
662		return s.runQuery(q), nil
663	}
664	
665	// parseQuery 对查询对象做严格校验：仅允许 op/name/start/end/labels，
666	// 拒绝重复键与未知字段；标量必须是精确的 JSON 类型，start/end 为 int64 毫秒。
667	func parseQuery(raw json.RawMessage) (parsedQuery, error) {
668		var q parsedQuery
669		err := parseStrictObject(raw,
670			"each query must be a JSON object",
671			"unexpected content after the query object",
672			[]string{"op", "name", "start", "end"},
673			map[string]fieldReader{
674				"op": func(dec *json.Decoder) error {
675					t, err := dec.Token()
676					if err != nil {
677						return err
678					}
679					op, ok := t.(string)
680					if !ok {
681						return fmt.Errorf(`field "op" must be a string`)
682					}
683					if op != "query" {
684						return fmt.Errorf(`unknown op %q (only "query" is supported)`, op)
685					}
686					return nil
687				},
688				"name":  func(dec *json.Decoder) error { return readNameField(dec, &q.name) },
689				"start": func(dec *json.Decoder) error { return readInt64Field(dec, "start", &q.start) },
690				"end":   func(dec *json.Decoder) error { return readInt64Field(dec, "end", &q.end) },
691				"labels": func(dec *json.Decoder) error {
692					return readLabelsField(dec, `field "labels" must be an object of non-empty string keys to string values`, &q.labels)
693				},
694			})
695		return q, err
696	}
697	
698	// labelsMatch 实现子集匹配：want 中每个键都必须在 stored 中存在且值完全相等，
699	// stored 可以含额外标签；空字符串值只匹配真实存在的空值标签。
700	func labelsMatch(want, stored map[string]string) bool {
701		for k, v := range want {
702			got, ok := stored[k]
703			if !ok || got != v {
704				return false
705			}
706		}
707		return true
708	}
709	
710	// runQuery 只读扫描已成功提交的数据：name 精确、标签子集、[start,end] 闭区间。
711	// 序列次序与写入快照共用 organizeSeries 的整理结果：过滤掉其他序列后，
712	// 保留的序列仍是同一排序中的一个子序列，不另换排序；无区间内点的序列不列出。
713	func (s *MetricStore) runQuery(q parsedQuery) *QueryResult {
714		inRange := func(ts int64) bool { return ts >= q.start && ts <= q.end }
715		out := make([]QuerySeries, 0)
716		for _, os := range s.organizeSeries() {
717			if os.ref.Name != q.name || !labelsMatch(q.labels, os.ref.Labels) {
718				continue
719			}
720			points := sortedSeriesPoints(os.sr, inRange)
721			if len(points) == 0 {
722				continue
723			}
724			values := make([]float64, len(points))
725			for i, p := range points {
726				values[i] = p.Value
727			}
728			out = append(out, QuerySeries{
729				Name:    os.ref.Name,
730				Labels:  os.ref.Labels,
731				Count:   len(values),
732				Average: finiteMean(values),
733			})
734		}
735		return &QueryResult{Status: "ok", Op: "query", Series: out}
736	}
737	
738	// finiteMean 返回已存储 float64 值的精确算术平均所对应的最近 float64，
739	// 恰好在两个相邻可表示值中间时按最近偶数舍入。
740	// 求和用有理数精确完成：与点的顺序、批次划分无关，正负大数抵消后的小余量
741	// 不会丢失，总和超出 float64 范围时结果仍然有限。精确平均为零时返回 +0；
742	// 只有一个点时结果就是该点的值。
743	func finiteMean(values []float64) float64 {
744		sum := new(big.Rat)
745		r := new(big.Rat)
746		for _, v := range values {
747			// 写入侧已保证 v 有限，SetFloat64 对有限值是精确的。
748			sum.Add(sum, r.SetFloat64(v))
749		}
750		sum.Quo(sum, r.SetInt64(int64(len(values))))
751		return ratToFloat64NearestEven(sum)
752	}
753	
754	// ratToFloat64NearestEven 把有理数 x 舍入到最近的 float64，半数取偶。
755	// 调用方保证 |x| 不超过 MaxFloat64（有限值的均值必然满足），因此不会溢出。
756	func ratToFloat64NearestEven(x *big.Rat) float64 {
757		if x.Sign() == 0 {
758			return 0
759		}
760		num := new(big.Int).Set(x.Num())
761		den := x.Denom()
762		neg := num.Sign() < 0
763		if neg {
764			num.Neg(num)
765		}
766	
767		// e 满足 2^e <= num/den < 2^(e+1)。
768		e := floorLog2Rat(num, den)
769		var m *big.Int
770		scale := 0
771		if e >= -1022 {
772			// 正规数：m 为 num/den 按 2^(e-52) 缩放后的 53 位舍入整数。
773			scale = e - 52
774			m = roundScaledRatio(num, den, scale)
775			if m.BitLen() == 54 {
776				// 舍入进位（如 1.111…1 进为 10.0），指数加一。
777				m.Rsh(m, 1)
778				scale++
779			}
780		} else {
781			// 次正规数：有效位间距固定为 2^-1074；m 舍入为 0 时按 IEEE 得到带符号零。
782			scale = -1074
783			m = roundScaledRatio(num, den, scale)
784		}
785		// m < 2^53，可以精确放入 int64 与 float64。
786		f := math.Ldexp(float64(m.Int64()), scale)
787		if neg {
788			return -f
789		}
790		return f
791	}
792	
793	// floorLog2Rat 返回正有理数 num/den 的二进制阶：最大的 e 使 2^e <= num/den。
794	func floorLog2Rat(num, den *big.Int) int {
795		k := num.BitLen() - den.BitLen()
796		var t big.Int
797		if k >= 0 {
798			t.Lsh(den, uint(k))
799			if num.Cmp(&t) >= 0 {
800				return k
801			}
802			return k - 1
803		}
804		t.Lsh(num, uint(-k))
805		if t.Cmp(den) >= 0 {
806			return k
807		}
808		return k - 1
809	}
810	
811	// roundScaledRatio 返回 round(num / (den · 2^scale))，半数取偶；num、den 均为正。
812	func roundScaledRatio(num, den *big.Int, scale int) *big.Int {
813		n := new(big.Int).Set(num)
814		d := new(big.Int).Set(den)
815		if scale >= 0 {
816			d.Lsh(d, uint(scale))
817		} else {
818			n.Lsh(n, uint(-scale))
819		}
820		q, r := new(big.Int).QuoRem(n, d, new(big.Int))
821		switch r2 := new(big.Int).Lsh(r, 1); r2.Cmp(d) {
822		case 1:
823			q.Add(q, big.NewInt(1))
824		case 0:
825			if q.Bit(0) == 1 {
826				q.Add(q, big.NewInt(1))
827			}
828		}
829		return q
830	}
831	
832	// String 让冲突原因中的序列身份可读且无歧义：name{k=v,...}，标签按键排序。
833	// 名称、标签键、标签值是不含分隔字符（逗号、等号、花括号、引号、反斜杠）、
834	// 不含首尾空白与不可打印字符的非空字符串时按原文呈现（cpu{host=a} 保持原样）；
835	// 否则以带引号的字符串字面量呈现，使内容字符与标签边界永远可以区分——
836	// 单标签值 "1,b=2" 渲染为 a="1,b=2"，与两标签 a=1,b=2 不再混淆；换行、
837	// 制表符等呈现为 \n、\t 这样的可辨认文字标记，一条冲突原因始终是一条记录；
838	// 空字符串值渲染为 ""，与无标签的 {} 明确区分。渲染只依赖解析后的真实身份，
839	// 与标签书写顺序、字符是否以 JSON 转义书写无关。
840	func (r SeriesRef) String() string {
841		var b strings.Builder
842		b.WriteString(identityText(r.Name))
843		b.WriteByte('{')
844		for i, p := range sortedPairs(r.Labels) {
845			if i > 0 {
846				b.WriteByte(',')
847			}
848			b.WriteString(identityText(p.Key))
849			b.WriteByte('=')
850			b.WriteString(identityText(p.Value))
851		}
852		b.WriteByte('}')
853		return b.String()
854	}
855	
856	// identityText 把身份组成部分（指标名、标签键、标签值）渲染为无歧义文本：
857	// 不含分隔字符、首尾空白与不可打印字符的非空字符串原样返回；其余情况用
858	// strconv.Quote 加引号并转义，引号边界标出内容的起止（首尾空格、空串可见），
859	// 控制字符呈现为 \n、\t 等转义标记。分隔字符与引号、反斜杠一律被引号包裹，
860	// 因此渲染结果不会把内容字符误读为标签边界。
861	func identityText(s string) string {
862		if s == "" || s != strings.TrimSpace(s) {
863			return strconv.Quote(s)
864		}
865		for _, r := range s {
866			if !unicode.IsPrint(r) || strings.ContainsRune(`,={}"\`, r) {
867				return strconv.Quote(s)
868			}
869		}
870		return s
871	}
872	
873	// organizedSeries 是一次结果整理中的一条序列：携带已存序列指针，
874	// 以及供结果直接使用的独立标签副本（标签书写顺序不影响身份，
875	// 副本使调用方对结果的修改不能回写存储）。
876	type organizedSeries struct {
877		sr  *storedSeries
878		ref SeriesRef
879	}
880	
881	// organizeSeries 是写入快照与区间查询共用的数据整理逻辑：
882	// 遍历全部已提交序列，复制各自的序列身份，并按唯一的顺序约定排列——
883	// 先按指标名字符串字典序，再按标签键升序后的键值对逐对比较
884	// （先比键再比值，前一对相同才比下一对；较短集合是完整前缀时排前，
885	// 无标签序列因此排在最前）。标签值按字符串比较（"10" 在 "2" 之前）。
886	// 整理结果不复制采样点；采样点的选取与升序排列由 sortedSeriesPoints 完成。
887	func (s *MetricStore) organizeSeries() []organizedSeries {
888		out := make([]organizedSeries, 0, len(s.series))
889		for _, sr := range s.series {
890			// 标签必须复制：成功结果是当次操作的独立记录，
891			// 调用方修改结果标签不能改动已存序列的身份。
892			out = append(out, organizedSeries{
893				sr:  sr,
894				ref: SeriesRef{Name: sr.ref.Name, Labels: cloneLabels(sr.ref.Labels)},
895			})
896		}
897		sort.Slice(out, func(i, j int) bool {
898			if out[i].ref.Name != out[j].ref.Name {
899				return out[i].ref.Name < out[j].ref.Name
900			}
901			return compareLabelPairs(sortedPairs(out[i].ref.Labels), sortedPairs(out[j].ref.Labels)) < 0
902		})
903		return out
904	}
905	
906	// sortedSeriesPoints 按 timestamp 升序返回一条已存序列中满足 keep 的采样点，
907	// 数值与时间戳一一对应。keep 为 nil 时返回全部点（写入快照）；
908	// 区间查询传入闭区间判定，查询只选取区间内的点。
909	// 返回的是新建切片与新建 Point，调用方对采样点的修改不影响存储，
910	// 也不影响此前或此后取得的其他成功结果。
911	func sortedSeriesPoints(sr *storedSeries, keep func(ts int64) bool) []Point {
912		tsList := make([]int64, 0, len(sr.points))
913		for ts := range sr.points {
914			if keep == nil || keep(ts) {
915				tsList = append(tsList, ts)
916			}
917		}
918		sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
919		points := make([]Point, len(tsList))
920		for i, ts := range tsList {
921			points[i] = Point{Timestamp: ts, Value: sr.points[ts]}
922		}
923		return points
924	}
925	
926	// snapshot 生成按规范排序的全部序列视图：序列次序与点排列均来自
927	// organizeSeries/sortedSeriesPoints 这套与查询共用的整理逻辑。
928	func (s *MetricStore) snapshot(added, duplicates int) *BatchResult {
929		organized := s.organizeSeries()
930		views := make([]SeriesView, 0, len(organized))
931		for _, os := range organized {
932			views = append(views, SeriesView{
933				Name:   os.ref.Name,
934				Labels: os.ref.Labels,
935				Points: sortedSeriesPoints(os.sr, nil),
936			})
937		}
938		return &BatchResult{Status: "ok", Added: added, Duplicates: duplicates, Series: views}
939	}
