501		// 查询不改变存储：同一查询重复结果一致，后续写入快照也不受影响。
502		res2 := mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":100}`)
503		if !reflect.DeepEqual(res, res2) {
504			t.Fatalf("repeated query differs: %+v vs %+v", res, res2)
505		}
506		snap := mustOK(t, store, `[]`)
507		if len(snap.Series) != 1 || len(snap.Series[0].Points) != 2 {
508			t.Fatalf("query mutated storage, snapshot = %+v", snap.Series)
509		}
